# Партия 1 — 28 августа 2026. Дозакрытие сторон сделок 2024 года (Этап 7,
# продолжение после 2026/2025 годов — см. коммиты «Этап 7, П1-7»/«П2-7»).
# Список кандидатов — все company_id, являющиеся buyer/seller_id/target/
# asset_id хотя бы одной сделки с датой 2024-*, ещё не в REGISTRY. Метод тот
# же: живой поиск ApiFnsClient.search(), решение чтением ОКВЭД/региона/
# организационно-правовой формы/даты регистрации против фактов сделки, не по
# одному совпадению имени. Живой WebSearch — только для нескольких
# высокопрофильных или структурно неоднозначных случаев (Р7/Р7-Офис, Каппа
# Рус/Окуловская бумажная фабрика, агрохолдинг «Покровский», «Эй Кей Раша»).
# Находка партии: свободный поиск ФНС по «Окуловская бумажная фабрика» дал
# ложное совпадение («Боровичская картонно-бумажная фабрика» — по улице
# «Окуловская» в адресе, не по названию компании) — верное юрлицо (ООО «Каппа
# Рус Окуловка», бывшая «Окуловская бумажная фабрика», переименована после
# покупки) нашлось только через прямой WebSearch на профильных отраслевых
# сайтах.
# ============================================================================
