def by_company_id() -> dict[str, dict]:
    return {row["company_id"]: row for row in REGISTRY}


def confirmed_inns() -> dict[str, str]:
    """company_id -> ИНН, только записи decision=confirmed с непустым inn."""
    return {row["company_id"]: row["inn"] for row in REGISTRY
            if row["decision"] == "confirmed" and row.get("inn")}
